def check_greater(tuple1, tuple2):
    if len(tuple1) != len(tuple2):
        raise ValueError("Tuples must be of the same length")
    return all(a > b for a, b in zip(tuple1, tuple2))

def check_K(test_tup, k):
    if not test_tup:
        return True
    for tup in test_tup:
        if k not in tup:
            return False
    return True

def check_K(tuples_list, k):
    # Condition 1: no tuple contains duplicates
    for t in tuples_list:
        if len(t) != len(set(t)):
            return False
    # Condition 2: k appears at least twice overall
    count = sum(1 for t in tuples_list for x in t if x == k)
    return count >= 2

def check_smaller(tuple1, tuple2):
    if len(tuple1) != len(tuple2):
        raise ValueError("Tuples must have the same length.")
    return all(x > y for x, y in zip(tuple1, tuple2))

def check_smaller(tuple1, tuple2):
    """
    Returns the count of indices where the element in tuple2 is strictly less than the element in tuple1.
    If tuples have different lengths, returns -1.
    """
    if len(tuple1) != len(tuple2):
        return -1
    count = 0
    for x, y in zip(tuple1, tuple2):
        if y < x:
            count += 1
    return count

